// Website chat message -> { channel, session_id, text }
const j = $input.first().json;
if (j.action && j.action !== 'sendMessage') return []; // the chat widget asking to reload an old session
return [{ json: { channel: 'website', session_id: 'web-' + j.sessionId, text: String(j.chatInput || '').slice(0, 2000), customer_name: '' } }];

// Turns every row of the FAQ sheet into "Topic: answer" lines for the assistant.
const lines = [];
for (const { json: row } of $input.all()) {
  const values = Object.entries(row).filter(([k, v]) => k !== 'row_number' && String(v ?? '').trim() !== '');
  if (!values.length) continue;
  lines.push(values.map(([k, v]) => String(v).trim()).join(': '));
}
return [{ json: { ...$('Read the message').first().json, knowledge: lines.join('\n') || '(The FAQ sheet is empty.)' } }];
